// Normal visible UI only; the global fail-closed mutation guard is unchanged.
import fixture from '../fixtures/cart-observed.json';
import { text, compact, ui, replayPresentation, afterBrowserRender } from './ordering';
import contract from './cart-contract.cjs';

export const products = fixture;
const itemSelector = 'main [data-cy="cart-item"]';
const key = intent => intent.product.slug + ':' + intent.pack.labels;
let selectionSequence = 0;

export function intent(product, pack, quantity) {
  return { product, pack, quantity };
}

function one($root, selector) {
  const $element = $root.find(selector);
  expect($element, 'one intended DOM field: ' + selector).to.have.length(1);
  expect($element, 'visible intended DOM field: ' + selector).to.be.visible;
  return $element;
}

function lineSnapshot($line) {
  const image = one($line, '.cart-thumb img').attr('src');
  const match = new URL(image, Cypress.config('baseUrl')).pathname.match(/^\/api\/v1\/products\/([^/]+)\/images\/[^/]+$/);
  expect(match, 'inspected cart image path carries a product slug').not.eq(null);
  const labels = text(one($line, '.cart-item__info small').text()).match(/^(\d+) بارکد در هر بسته$/);
  expect(labels, 'explicit labels-per-package unit, not total labels').not.eq(null);
  const quantity = text(one($line, '.cart-quantity-val').text());
  expect(quantity, 'visible quantity is an integer').match(/^\d+$/);
  const amount = compact(one($line, '.cart-item__price').text());
  expect(amount, 'cart line amount has an explicit IRR unit').match(/^\d+ریال$/);
  return { slug: match[1], name: one($line, 'h2').text().trim(), labels: Number(labels[1]),
    quantity: Number(quantity), amount: Number(amount.replace('ریال', '')) };
}

export function assertCart(intents) {
  let verifiedSnapshot;
  cy.location('pathname').should('eq', '/cart');
  // One retryable DOM snapshot; expected identity/quantity comes from suite intent.
  cy.get('main').should('have.length', 1).should($main => {
    const $summary = one($main, '.order-summary');
    const $countLabel = $summary.find('p').filter((_, p) => text(p.textContent) === 'تعداد بسته');
    expect($countLabel, 'summary unit is explicitly packages').to.have.length(1);
    expect($countLabel).to.be.visible;
    const $count = one($countLabel.parent(), 'strong');
    const countText = text($count.text());
    expect(countText, 'summary package count is numeric').match(/^\d+$/);
    const snapshot = { path: $main[0].ownerDocument.location.pathname,
      emptyVisible: $main.find('.commerce-empty:visible').length > 0,
      lines: $main.find('[data-cy="cart-item"]').toArray().map(el => {
        expect(Cypress.$(el), 'each actual cart line is visible').to.be.visible;
        return lineSnapshot(Cypress.$(el));
      }), packageCount: Number(countText) };
    contract.assertCartSnapshot(snapshot, intents);
    verifiedSnapshot = snapshot;
  });
  cy.then(() => {
    const checkpoints = Cypress.expose('cartCheckpoints') || [];
    checkpoints.push({ at: new Date().toISOString(), actual: verifiedSnapshot,
      expected: intents.map(row => ({ slug: row.product.slug, name: row.product.name,
        labels: row.pack.labels, quantity: row.quantity, quotePresentationAmount: row.amount })) });
    Cypress.expose('cartCheckpoints', checkpoints);
  });
}

export function assertEmpty() {
  cy.location('pathname').should('eq', '/cart');
  cy.get(itemSelector).should('not.exist');
  cy.get('main .commerce-empty').should('have.length', 1).and('be.visible');
}

export function installOwnedCartHooks() {
  let owned = [], active = false;
  beforeEach(() => {
    owned = []; active = false;
    Cypress.expose('cartCheckpoints', []);
    Cypress.expose('cartCleanup', { state: 'not-started' });
    cy.intercept('GET', '/api/v1/auth/session').as('cartGuest');
    cy.visit('/cart');
    cy.wait('@cartGuest').then(({ response }) => {
      expect(response.statusCode, 'real ordinary guest session endpoint').eq(200);
      expect(response.body, 'session has an explicit user field').to.have.property('user', null);
    });
    assertEmpty();
    cy.then(() => { active = true; Cypress.expose('cartCleanup', { state: 'verified-initial-empty' }); });
  });
  afterEach(() => {
    if (!active) return; // Never clean a cart whose empty/guest prerequisite failed.
    cy.visit('/cart');
    // A document load can finish before the client cart hydrates. Wait for an
    // actual rendered cart state before deciding whether there is work to remove.
    cy.get('main .commerce-empty, main [data-cy="cart-item"]').filter(':visible')
      .should('have.length.greaterThan', 0);
    function removeOwned() {
      cy.get('main').then($main => {
        const $lines = $main.find('[data-cy="cart-item"]');
        if (!$lines.length) { assertEmpty(); return; }
        // Inspect every remaining line before deleting anything. Only inspected
        // product/package identities from this test's actions qualify as owned.
        $lines.toArray().forEach(el => {
          const line = lineSnapshot(Cypress.$(el));
          expect(owned.some(row => row.product.slug === line.slug && row.product.name === line.name &&
            row.pack.labels === line.labels), 'cleanup refuses an unowned configuration').eq(true);
        });
        const before = $lines.length;
        cy.wrap($lines.first()).contains('button', /^حذف$/).should('be.visible').and('be.enabled').click();
        cy.get(itemSelector).should('have.length', before - 1);
        cy.then(removeOwned);
      });
    }
    cy.then(removeOwned);
    cy.then(() => { Cypress.expose('cartCleanup', { state: 'verified-empty-after-normal-remove',
      owned: owned.map(row => key(row)), storageResetUsed: false }); });
  });
  return entry => { if (!owned.some(row => key(row) === key(entry))) owned.push(entry); };
}

export function selectAndAdd(entry, registerOwned, viewport = 'desktop') {
  const quotePath = '/api/v1/products/' + entry.product.slug + '/quote';
  let settledQuote;
  // A cart may re-quote earlier items. Each independent product visit needs its
  // own queue so a previous visit's exchanges cannot satisfy a new action wait.
  const quoteAlias = 'cartSelectionQuote' + (++selectionSequence);
  cy.intercept('POST', quotePath).as(quoteAlias);
  cy.visit(entry.product.path);
  cy.get('main h1').should('have.text', entry.product.name).and('be.visible');
  function waitQuote(quantity, pack) {
    return cy.wait('@' + quoteAlias).then(({ request, response }) => {
      expect(new URL(request.url).pathname, 'exact intended product quote').eq(quotePath);
      expect(request.body).deep.eq({ package_id: pack.id, quantity });
      expect(response.statusCode, 'completed quote readiness only').eq(200);
      expect(response.body, 'quote identity and labels correlate with intent').include({
        package_id: pack.id, quantity, labels_per_package: pack.labels, labels_total: quantity * pack.labels
      });
      replayPresentation(response.body);
      return cy.then(() => { settledQuote = response.body; });
    });
  }
  waitQuote(1, entry.product.default);
  if (entry.pack.id !== entry.product.default.id) {
    cy.contains('main .package-options-grid button', entry.pack.title)
      .should('be.visible').and('be.enabled').click();
    waitQuote(1, entry.pack);
  }
  for (let q = 2; q <= entry.quantity; q++) {
    cy.get(ui.increase).should('have.length', 1).and('be.visible').and('be.enabled').click();
    waitQuote(q, entry.pack);
  }
  cy.get('main .package-options-grid button.is-selected').should('have.length', 1)
    .find('.package-card-title').should('have.text', entry.pack.title);
  cy.get(ui.quantity).should('have.value', String(entry.quantity));
  // Capture only settled, correlated quote presentation. No independent price claim.
  cy.then(() => { entry.amount = settledQuote.line_total_irr; });
  cy.then(() => registerOwned(entry)); // Before Add so cleanup can recover after an assertion failure.
  if (viewport === 'narrow') {
    cy.get('[data-cy="add-to-cart"]').should('not.be.visible');
    cy.get('main .product-mobile-bar button.mobile-bar-cta').should('have.length', 1)
      .and('have.text', 'افزودن به سبد خرید').and('be.visible').and('be.enabled').click();
  } else {
    cy.get('main [data-cy="add-to-cart"]').should('have.length', 1)
      .and('contain.text', 'افزودن به سبد خرید').and('be.visible').and('be.enabled').click();
  }
  cy.location('pathname').should('eq', '/cart');
  afterBrowserRender();
}
